// Prepare transcript window text for LLM analysis
const body = $input.first().json.body || $input.first().json;
const transcript = body.transcript_window || [];

const windowText = transcript.map(line => `[${line.language || 'auto'}] ${line.text}`).join('\n');

return {
  json: {
    session_id: body.session_id || 'unknown',
    window_text: windowText,
    line_count: transcript.length
  }
};

// Parse and normalize LLM response to 0-100 scale and threshold categories
const input = $input.first().json;
let parsed = {};

try {
  const responseText = input.text || input.response || (typeof input === 'string' ? input : JSON.stringify(input));
  // Extract JSON block if wrapped in markdown
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = JSON.parse(responseText);
  }
} catch (e) {
  parsed = {
    risk_score: 0,
    flagged_phrases: [],
    reasoning_trace: 'Failed to parse LLM structured output'
  };
}

const score = Math.max(0, Math.min(100, Math.round(Number(parsed.risk_score) || 0)));
const level = score >= 70 ? 'DANGER' : score >= 40 ? 'CAUTION' : 'SAFE';

return {
  json: {
    risk_score: score,
    threat_level: level,
    flagged_phrases: Array.isArray(parsed.flagged_phrases) ? parsed.flagged_phrases : [],
    reasoning_trace: parsed.reasoning_trace || 'Evaluated transcript against financial fraud markers.',
    timestamp: new Date().toISOString()
  }
};
